//! Bevy application shared by desktop and mobile entry points.

/// Start the application event loop.
pub fn run() {
    use bevy::prelude::*;
    App::new()
        .add_plugins(DefaultPlugins.set(WindowPlugin {
            primary_window: Some(Window {
                title: "Overpalancing".into(),
                ..default()
            }),
            ..default()
        }))
        .run();
}

/// Mobile entry point generated by Bevy on Android and iOS.
#[cfg(any(target_os = "android", target_os = "ios"))]
#[bevy::prelude::bevy_main]
fn main() {
    run();
}
